class Solution:
    def maxScore(self, points: list[int], m: int) -> int:
        n = len(points)
        if m < n:
            return 0

        suff0 = [0] * n
        suff1 = [0] * n

        def check(X: int) -> bool:
            req_n1 = (X + points[n - 1] - 1) // points[n - 1]
            a_n1 = max(req_n1 - 1, 0)

            suff0[n - 1] = 0
            suff1[n - 1] = a_n1

            for i in range(n - 2, -1, -1):
                req = (X + points[i] - 1) // points[i]
                b = max(req - 2, 0)

                s0 = suff0[i + 1]
                s1 = suff1[i + 1]
                suff0[i] = max(s0, s1)
                suff1[i] = s0 + b

            if 2 * n - 1 + 2 * max(suff0[0], suff1[0]) <= m:
                return True

            p0 = 0
            p1 = 0

            for F in range(1, n):
                i = F - 1
                req = (X + points[i] - 1) // points[i]
                a = max(req - 1, 0)

                p0, p1 = max(p0, p1), p0 + a

                s0 = suff0[F]
                s1 = suff1[F]

                max_is = max(p0 + max(s0, s1), p1 + s0)

                if 2 * n - F - 1 + 2 * max_is <= m:
                    return True

            return False

        low = 1
        high = max(points) * m
        ans = 0

        while low <= high:
            mid = (low + high) // 2
            if check(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1

        return ans
